codeExercises.solution:
M = 4
NODES = [0, 1, 3, 5, 6, 8, 11, 15]

def cpl(a: int, b: int, m: int = M) -> int:
    x = a ^ b
    return m if x == 0 else m - x.bit_length()

def routing_table(me: int, nodes: list[int], k: int = 1, m: int = M) -> list[list[int]]:
    """Riga P = contatti con prefisso comune lungo esattamente P.
    Con più candidati del necessario tiene i k più vicini (scelta arbitraria ma deterministica)."""
    table = []
    for P in range(m):
        cands = [n for n in nodes if n != me and cpl(me, n) == P]
        cands.sort(key=lambda n: n ^ me)
        table.append(cands[:k])
    return table

def owner(key: int, nodes: list[int]) -> int:
    return min(nodes, key=lambda n: n ^ key)

for me in NODES:
    t = routing_table(me, NODES)
    row = "  ".join(f"P{P}:{('N'+str(c[0])) if c else '-':>4}" for P, c in enumerate(t))
    print(f"N{me:<2} ({me:04b})  {row}")

print()
for key in [3, 4, 7, 9, 12]:
    print(f"k{key} ({key:04b}) -> N{owner(key, NODES)}")

# quante voci possibili ha ogni riga (candidati) per N6?
print()
for P in range(M):
    print("N6 riga", P, "candidati:", [n for n in NODES if n != 6 and cpl(6, n) == P])

