codeExercises.solution:
import random, math

M, K, ALPHA = 32, 8, 3
random.seed(2026)
N = 2000
ids = random.sample(range(2**M), N)

def bucket(a, b):
    return (a ^ b).bit_length() - 1

# tabelle di routing: per ogni bucket al più K contatti scelti a caso tra i candidati
tables = {}
for me in ids:
    buckets = {}
    for other in ids:
        if other != me:
            buckets.setdefault(bucket(me, other), []).append(other)
    tables[me] = {i: random.sample(c, min(K, len(c))) for i, c in buckets.items()}

def find_node(w, target):
    """RPC FIND_NODE: i K contatti di w più vicini a target."""
    known = [c for lst in tables[w].values() for c in lst]
    return sorted(known, key=lambda c: c ^ target)[:K]

def lookup(src, target):
    shortlist = sorted({c for lst in tables[src].values() for c in lst}, key=lambda c: c ^ target)[:K]
    queried, rounds, messages = set(), 0, 0
    closest = shortlist[0]
    while True:
        batch = [c for c in shortlist if c not in queried][:ALPHA]
        if not batch:
            break
        rounds += 1
        for c in batch:
            queried.add(c); messages += 1
            shortlist = sorted(set(shortlist) | set(find_node(c, target)), key=lambda x: x ^ target)[:K]
        if shortlist[0] ^ target >= closest ^ target:
            # nessun miglioramento: interroga tutti i K più vicini rimasti e termina
            rest = [c for c in shortlist if c not in queried]
            for c in rest:
                queried.add(c); messages += 1
                shortlist = sorted(set(shortlist) | set(find_node(c, target)), key=lambda x: x ^ target)[:K]
            if rest:
                rounds += 1
            break
        closest = shortlist[0]
    return shortlist, rounds, messages

ok, R, MSG = 0, [], []
for _ in range(300):
    src, tgt = random.sample(ids, 2)
    res, r, msg = lookup(src, tgt)
    true_k = sorted(ids, key=lambda x: x ^ tgt)[:K]
    ok += (res[0] == tgt) and (set(res) == set(true_k))
    R.append(r); MSG.append(msg)
print(f"N = {N}, log2 N = {math.log2(N):.1f}")
print(f"lookup corretti (target trovato e k più vicini esatti): {ok}/300")
print(f"round medi: {sum(R)/len(R):.2f}, max {max(R)}")
print(f"messaggi FIND_NODE medi: {sum(MSG)/len(MSG):.1f}")
